//! Box styles compared with Python Rich 15, using `tests/fixtures/box.golden`
//! (generated by `scripts/gen_box_golden.py`).
//!
//! For each of Rich's 19 boxes: the `BoxStyle` constant must match the box
//! lines Rich defines, and a Table (plain, with row lines, without edge,
//! without header) and a titled Panel drawn with the matching `BorderStyle` must equal
//! Rich's plain output.
//!
//! fast-rich's `BoxStyle` has 6 of Rich's 8 lines: Rich's `foot_row` and
//! `foot` (lines 6 and 7) only draw table footers, which fast-rich does not
//! have yet, so they are not compared. Rich's `Box.substitute` (legacy
//! Windows / ASCII-only consoles) is not ported; the golden is rendered
//! without it.

use fast_rich::box_drawing::{self, BoxStyle, Line};
use fast_rich::panel::{BorderStyle, Panel};
use fast_rich::renderable::{render_lines, Renderable};
use fast_rich::style::Style;
use fast_rich::table::{Column, Table};

const GOLDEN: &str = include_str!("fixtures/box.golden");

const BOXES: [(&str, BorderStyle, BoxStyle); 19] = [
    ("ASCII", BorderStyle::Ascii, box_drawing::ASCII),
    ("ASCII2", BorderStyle::Ascii2, box_drawing::ASCII2),
    (
        "ASCII_DOUBLE_HEAD",
        BorderStyle::AsciiDoubleHead,
        box_drawing::ASCII_DOUBLE_HEAD,
    ),
    ("SQUARE", BorderStyle::Square, box_drawing::SQUARE),
    (
        "SQUARE_DOUBLE_HEAD",
        BorderStyle::SquareDoubleHead,
        box_drawing::SQUARE_DOUBLE_HEAD,
    ),
    ("MINIMAL", BorderStyle::Minimal, box_drawing::MINIMAL),
    (
        "MINIMAL_HEAVY_HEAD",
        BorderStyle::MinimalHeavyHead,
        box_drawing::MINIMAL_HEAVY_HEAD,
    ),
    (
        "MINIMAL_DOUBLE_HEAD",
        BorderStyle::MinimalDoubleHead,
        box_drawing::MINIMAL_DOUBLE_HEAD,
    ),
    ("SIMPLE", BorderStyle::Simple, box_drawing::SIMPLE),
    (
        "SIMPLE_HEAD",
        BorderStyle::SimpleHead,
        box_drawing::SIMPLE_HEAD,
    ),
    (
        "SIMPLE_HEAVY",
        BorderStyle::SimpleHeavy,
        box_drawing::SIMPLE_HEAVY,
    ),
    (
        "HORIZONTALS",
        BorderStyle::Horizontals,
        box_drawing::HORIZONTALS,
    ),
    ("ROUNDED", BorderStyle::Rounded, box_drawing::ROUNDED),
    ("HEAVY", BorderStyle::Heavy, box_drawing::HEAVY),
    (
        "HEAVY_EDGE",
        BorderStyle::HeavyEdge,
        box_drawing::HEAVY_EDGE,
    ),
    (
        "HEAVY_HEAD",
        BorderStyle::HeavyHead,
        box_drawing::HEAVY_HEAD,
    ),
    ("DOUBLE", BorderStyle::Double, box_drawing::DOUBLE),
    (
        "DOUBLE_EDGE",
        BorderStyle::DoubleEdge,
        box_drawing::DOUBLE_EDGE,
    ),
    ("MARKDOWN", BorderStyle::Markdown, box_drawing::MARKDOWN),
];

/// `(box, kind) -> lines` from the golden, in file order.
fn records() -> Vec<(String, String, Vec<String>)> {
    let mut out: Vec<(String, String, Vec<String>)> = Vec::new();
    for line in GOLDEN.lines() {
        if let Some(head) = line.strip_prefix("@ ") {
            let (name, kind) = head.split_once(' ').unwrap();
            out.push((name.into(), kind.into(), Vec::new()));
        } else if let Some(body) = line.strip_prefix('>') {
            out.last_mut().unwrap().2.push(body.to_string());
        }
    }
    out
}

fn golden(name: &str, kind: &str) -> Vec<String> {
    records()
        .into_iter()
        .find(|(n, k, _)| n == name && k == kind)
        .unwrap_or_else(|| panic!("{name} {kind} not in golden"))
        .2
}

fn plain(r: &dyn Renderable, width: usize) -> Vec<String> {
    render_lines(r, width, Style::new())
        .iter()
        .map(|l| l.iter().map(|s| s.text.as_ref()).collect::<String>())
        .map(|l| l.trim_end().to_string())
        .collect()
}

/// Rich's line string: left, horizontal, divider/cross, right.
fn rich_line(line: &Line) -> String {
    [line.left, line.mid, line.cross, line.right]
        .iter()
        .collect()
}

fn table(style: BorderStyle) -> Table {
    let mut t = Table::new().border_style(style);
    t.add_column("Name");
    t.add_column(Column::new("Qty").right());
    t.add_row_strs(&["apple", "3"]);
    t.add_row_strs(&["kiwi", "12"]);
    t.add_row_strs(&["fig", "7"]);
    t
}

#[test]
fn golden_covers_every_rich_box_in_order() {
    let names: Vec<String> = records()
        .into_iter()
        .filter(|(_, k, _)| k == "lines")
        .map(|(n, _, _)| n)
        .collect();
    let ours: Vec<&str> = BOXES.iter().map(|(n, _, _)| *n).collect();
    assert_eq!(names, ours);
}

#[test]
fn box_constants_match_rich_definitions() {
    let mut failures = Vec::new();
    for (name, style, b) in BOXES {
        assert_eq!(style.to_box(), b, "{name}: BorderStyle::to_box");
        let rich = golden(name, "lines");
        // Rich's 8 lines; 6 (foot_row) and 7 (foot) have no BoxStyle field.
        let ours = [
            (0, b.top),
            (1, b.header),
            (2, b.head),
            (3, b.cell),
            (4, b.mid),
            (7, b.bottom),
        ];
        for (i, line) in ours {
            if rich_line(&line) != rich[i] {
                failures.push(format!(
                    "{name} line {}: {:?} != rich {:?}",
                    i + 1,
                    rich_line(&line),
                    rich[i]
                ));
            }
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn tables_and_panels_match_rich() {
    let mut failures = Vec::new();
    let mut count = 0;
    for (name, style, _) in BOXES {
        let cases: [(&str, Box<dyn Renderable>); 5] = [
            ("table", Box::new(table(style))),
            ("table_lines", Box::new(table(style).show_row_lines(true))),
            ("table_noedge", Box::new(table(style).show_edge(false))),
            ("table_noheader", Box::new(table(style).show_header(false))),
            (
                "panel",
                Box::new(
                    Panel::new("Hello\nWorld")
                        .border_style(style)
                        .width(20)
                        .title("Title"),
                ),
            ),
        ];
        for (kind, r) in cases {
            let want = golden(name, kind);
            let got = plain(r.as_ref(), 40);
            if got != want {
                failures.push(format!(
                    "{name} {kind}:\n--- ours\n{}\n--- rich\n{}",
                    got.join("\n"),
                    want.join("\n")
                ));
            }
            count += 1;
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
    assert_eq!(count, 95);
}
